from object_detector_tool import execution as tool

def count_toilets():
    # Path to the image containing toilets
    image_path = "/home/stud/wxie/BLINK_Dataset/Counting/val/images/val_Counting_20_image_1.jpg"

    # Detect toilet buckets in the image and their bounding boxes
    execution = tool.execute(image=image_path, labels=["toilet"])
    if execution:
        detected_bodies = []
        for body in execution:
            if "class_name" in body:
                if body["class_name"] == "toilet":
                    detected_bodies.append(body)

        # Count the visible toilets in the image
        visible_toilets = []
        for body in detected_bodies:
            (body["bbox_y1"], body["bbox_x2"], body["bbox_y2"], body["bbox_x1"]) = body["bbox"]
            visible_toilets.append("{0}.0, {1}.0".format(body["bbox_x1"], body["bbox_y1"]))

        return len(visible_toilets)
    else:
        return False

